// Narration timing (authoritative animation timeline). Generated by audio/narration.py -> audio/out/narration_timing.json
// and copied here as lib/timing.json by tools/sync-timing.mjs. Falls back to storyboard targets if missing.
import timing from './timing.json' with { type: 'json' };
const FALLBACK = [[0,24],[24,53],[53,76],[76,108],[108,138],[138,168],[168,200],[200,242],[242,273],[273,300]];
export const TIMING = timing;
export const T = {
  total: timing.total ?? 300,
  ch(id) {
    const c = (timing.chapters || []).find((c) => c.id === id);
    if (c) return c;
    const [s, e] = FALLBACK[id - 1]; return { id, start: s, end: e, sentences: [] };
  },
  // start time of the sentence in chapter `id` whose text includes `needle` (case-insensitive); fallback to given default
  sent(id, needle, dflt = null) {
    const c = this.ch(id); const n = needle.toLowerCase();
    const s = (c.sentences || []).find((x) => x.text.toLowerCase().includes(n));
    return s ? s : (dflt !== null ? { start: dflt, end: dflt + 3 } : { start: c.start, end: c.start + 3 });
  },
};
